import math
import statistics

def features(history,cell,target,current,position):
    result=[current[cell],current[target],current[target]-current[cell]]
    for cid in (cell,target):
        h=history[cid];q=[x[0] for x in h];p=[x[1] for x in h]
        result.extend([sum(q[-w:])/len(q[-w:]) for w in (3,5,10,20)])
        mean=sum(q)/len(q)
        result.extend([min(q),max(q),(sum((v-mean)**2 for v in q)/len(q))**.5])
        result.extend([q[-1]-q[max(0,len(q)-1-d)] for d in (1,3,5,10,19)])
        result.extend([p[-1],sum(p[-5:])/len(p[-5:]),p[-1]-p[0]])
    others=[v for k,v in current.items() if k not in (cell,target)]
    result.extend([max(others) if others else -60,history[target][-1][1]-history[cell][-1][1]])
    speed,z,heading=position
    result.extend([speed,z,math.sin(math.radians(heading)),math.cos(math.radians(heading))])
    return result

def finite(value):
    try:
        number=float(value)
        return number if math.isfinite(number) else None
    except (TypeError,ValueError,OverflowError):
        return None

